import java.util.function.Supplier;

public class Main {
    public static void main(String[] args) {
        System.out.println("1. Versi biasa, log mati");
        logBiasa(false, buatLaporan());

        System.out.println("2. Versi Supplier, log mati");
        logLazy(false, () -> buatLaporan());

        System.out.println("3. Versi Supplier, log hidup");
        logLazy(true, () -> buatLaporan());

        System.out.println("Laporan disusun " + dihitung + " kali");
    }

    static int dihitung = 0;

    static String buatLaporan() {
        dihitung++;
        System.out.println("   (menyusun laporan...)");
        return "Laporan #" + dihitung;
    }

    static void logBiasa(boolean aktif, String pesan) {
        if (aktif) {
            System.out.println("LOG: " + pesan);
        }
    }

    static void logLazy(boolean aktif, Supplier<String> pesan) {
        if (aktif) {
            System.out.println("LOG: " + pesan.get());
        }
    }
}

