interface Wadah<T> {
    void simpan(T x);
    T ambil();
}

class WadahTeks implements Wadah<String> {
    private String isi = "";

    public void simpan(String x) {
        isi = x.trim();
    }

    public String ambil() {
        return isi;
    }
}

class WadahApa<T> implements Wadah<T> {
    private T isi;

    public void simpan(T x) {
        isi = x;
    }

    public T ambil() {
        return isi;
    }
}

