import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    public static void main(String[] args) {
        String[] belanja = {
            "Kopi Susu;2;18000",
            "Roti Bakar;1;15000",
            "Air Mineral;3;5000"
        };

        StringBuilder struk = new StringBuilder();
        BigDecimal subtotal = BigDecimal.ZERO;

        for (String baris : belanja) {
            String[] bagian = baris.split(";");
            String nama = bagian[0];
            int qty = Integer.parseInt(bagian[1]);
            BigDecimal harga = new BigDecimal(bagian[2]);
            BigDecimal jumlah = harga.multiply(new BigDecimal(qty));
            subtotal = subtotal.add(jumlah);
            struk.append(String.format("%-12s %d x %6s = %6s\n", nama, qty, harga, jumlah));
        }

        BigDecimal pajak = subtotal.multiply(new BigDecimal("0.11")).setScale(0, RoundingMode.HALF_UP);
        BigDecimal total = subtotal.add(pajak);

        struk.append("Subtotal: ").append(subtotal).append("\n");
        struk.append("PPN 11%: ").append(pajak).append("\n");
        struk.append("Total bayar: ").append(total).append("\n");
        System.out.print(struk);
    }
}

